enum class Operator(val symbol: String) { PLUS("+"), MINUS("-"), TIMES("*"), DIVIDE("/"), MOD("%") }

sealed interface CalcResult {
    data class Ok(val value: Double) : CalcResult
    data class Error(val message: String) : CalcResult
}

fun calculate(line: String): CalcResult {
    val parts = line.trim().split(Regex("\\s+"))
    if (parts.size != 3) return CalcResult.Error("Use the form: 12 + 3")
    val a = parts[0].toDoubleOrNull() ?: return CalcResult.Error("'${parts[0]}' is not a number")
    val op = Operator.entries.firstOrNull { it.symbol == parts[1] } ?: return CalcResult.Error("Unknown operator '${parts[1]}'")
    val b = parts[2].toDoubleOrNull() ?: return CalcResult.Error("'${parts[2]}' is not a number")
    return apply(a, op, b)
}
